292|// GetCoverFromPath accepts a path to a file, and returns a path to an eligible cover image from the
293|// file's directory (as configured with CoverArtPriority). If no cover file is found, among
294|// available choices, or an error occurs, an empty string is returned. If HasEmbeddedCover is true,
295|// and 'embedded' is matched among eligible choices, GetCoverFromPath will return early with an
296|// empty path.
297|func getCoverFromPath(mediaPath string, embeddedPath string) string {
298|	n, err := os.Open(filepath.Dir(mediaPath))
299|	if err != nil {
300|		return ""
301|	}
302|
303|	defer n.Close()
304|	names, err := n.Readdirnames(-1)
305|	if err != nil {
306|		return ""
307|	}
308|
309|	for _, p := range strings.Split(conf.Server.CoverArtPriority, ",") {
310|		pat := strings.ToLower(strings.TrimSpace(p))
311|		if pat == "embedded" {
312|			if embeddedPath != "" {
313|				return ""
314|			}
315|			continue
316|		}
317|
318|		for _, name := range names {
319|			match, _ := filepath.Match(pat, strings.ToLower(name))
320|			if match && utils.IsImageFile(name) {
321|				return filepath.Join(filepath.Dir(mediaPath), name)
322|			}
323|		}
324|	}
325|
326|	return ""
327|}
