302|		if req.packName != ovalPack.Name {
303|			continue
304|		}
305|
306|		switch family {
307|		case constant.Oracle, constant.Amazon:
308|			if ovalPack.Arch == "" {
309|				logging.Log.Infof("Arch is needed to detect Vulns for Amazon and Oracle Linux, but empty. You need refresh OVAL maybe. oval: %#v, defID: %s", ovalPack, def.DefinitionID)
310|				continue
311|			}
312|		}
313|
314|		if ovalPack.Arch != "" && req.arch != ovalPack.Arch {
315|			continue
316|		}
317|
318|		// https://github.com/aquasecurity/trivy/pull/745
319|		if strings.Contains(req.versionRelease, ".ksplice1.") != strings.Contains(ovalPack.Version, ".ksplice1.") {
320|			continue
321|		}
322|
323|		isModularityLabelEmptyOrSame := false
324|		if ovalPack.ModularityLabel != "" {
325|			for _, mod := range enabledMods {
326|				if mod == ovalPack.ModularityLabel {
327|					isModularityLabelEmptyOrSame = true
328|					break
329|				}
330|			}
331|		} else {
332|			isModularityLabelEmptyOrSame = true
333|		}
334|		if !isModularityLabelEmptyOrSame {
335|			continue
336|		}
337|
338|		if running.Release != "" {
339|			switch family {
340|			case constant.RedHat, constant.CentOS, constant.Oracle:
341|				// For kernel related packages, ignore OVAL information with different major versions
342|				if _, ok := kernelRelatedPackNames[ovalPack.Name]; ok {
343|					if util.Major(ovalPack.Version) != util.Major(running.Release) {
344|						continue
345|					}
346|				}
347|			}
348|		}
