358|				err, req.versionRelease, ovalPack, def.DefinitionID)
359|			return false, false, ovalPack.Version, nil
360|		}
361|		if less {
362|			if req.isSrcPack {
363|				// Unable to judge whether fixed or not-fixed of src package(Ubuntu, Debian)
364|				return true, false, ovalPack.Version, nil
365|			}
366|
