238|func getDefsByPackNameFromOvalDB(driver db.DB, r *models.ScanResult) (relatedDefs ovalResult, err error) {
239|	requests := []request{}
240|	for _, pack := range r.Packages {
241|		requests = append(requests, request{
242|			packName:          pack.Name,
243|			versionRelease:    pack.FormatVer(),
244|			newVersionRelease: pack.FormatNewVer(),
245|			arch:              pack.Arch,
246|			isSrcPack:         false,
247|		})
248|	}
249|	for _, pack := range r.SrcPackages {
250|		requests = append(requests, request{
251|			packName:        pack.Name,
252|			binaryPackNames: pack.BinaryNames,
253|			versionRelease:  pack.Version,
254|			arch:            pack.Arch,
255|			isSrcPack:       true,
256|		})
257|	}
258|
259|	ovalFamily, err := GetFamilyInOval(r.Family)
260|	if err != nil {
261|		return relatedDefs, err
262|	}
263|
264|	for _, req := range requests {
265|		definitions, err := driver.GetByPackName(ovalFamily, r.Release, req.packName, req.arch)
266|		if err != nil {
267|			return relatedDefs, xerrors.Errorf("Failed to get %s OVAL info by package: %#v, err: %w", r.Family, req, err)
268|		}
269|		for _, def := range definitions {
270|			affected, notFixedYet, fixedIn, err := isOvalDefAffected(def, req, ovalFamily, r.RunningKernel, r.EnabledDnfModules)
271|			if err != nil {
272|				return relatedDefs, xerrors.Errorf("Failed to exec isOvalAffected. err: %w", err)
273|			}
274|			if !affected {
275|				continue
276|			}
277|
278|			if req.isSrcPack {
279|				for _, binName := range req.binaryPackNames {
280|					fs := fixStat{
281|						notFixedYet: false,
282|						isSrcPack:   true,
283|						fixedIn:     fixedIn,
284|						srcPackName: req.packName,
285|					}
286|					relatedDefs.upsert(def, binName, fs)
287|				}
288|			} else {
289|				fs := fixStat{
290|					notFixedYet: notFixedYet,
291|					fixedIn:     fixedIn,
292|				}
293|				relatedDefs.upsert(def, req.packName, fs)
294|			}
295|		}
296|	}
297|	return
298|}
