300|func isOvalDefAffected(def ovalmodels.Definition, req request, family string, running models.Kernel, enabledMods []string) (affected, notFixedYet bool, fixedIn string, err error) {
301|	for _, ovalPack := range def.AffectedPacks {
302|		if req.packName != ovalPack.Name {
303|			continue
304|		}
305|
306|		switch family {
307|		case constant.Oracle, constant.Amazon:
308|			if ovalPack.Arch == "" {
309|				logging.Log.Infof("Arch is needed to detect Vulns for Amazon and Oracle Linux, but empty. You need refresh OVAL maybe. oval: %#v, defID: %s", ovalPack, def.DefinitionID)
310|				continue
311|			}
312|		}
313|
314|		if ovalPack.Arch != "" && req.arch != ovalPack.Arch {
315|			continue
316|		}
317|
318|		// https://github.com/aquasecurity/trivy/pull/745
319|		if strings.Contains(req.versionRelease, ".ksplice1.") != strings.Contains(ovalPack.Version, ".ksplice1.") {
320|			continue
321|		}
322|
323|		isModularityLabelEmptyOrSame := false
324|		if ovalPack.ModularityLabel != "" {
325|			for _, mod := range enabledMods {
326|				if mod == ovalPack.ModularityLabel {
327|					isModularityLabelEmptyOrSame = true
328|					break
329|				}
330|			}
331|		} else {
332|			isModularityLabelEmptyOrSame = true
333|		}
334|		if !isModularityLabelEmptyOrSame {
335|			continue
336|		}
337|
338|		if running.Release != "" {
339|			switch family {
340|			case constant.RedHat, constant.CentOS, constant.Oracle:
341|				// For kernel related packages, ignore OVAL information with different major versions
342|				if _, ok := kernelRelatedPackNames[ovalPack.Name]; ok {
343|					if util.Major(ovalPack.Version) != util.Major(running.Release) {
344|						continue
345|					}
346|				}
347|			}
348|		}
349|
350|		if ovalPack.NotFixedYet {
351|			return true, true, ovalPack.Version, nil
352|		}
353|
354|		// Compare between the installed version vs the version in OVAL
355|		less, err := lessThan(family, req.versionRelease, ovalPack)
356|		if err != nil {
357|			logging.Log.Debugf("Failed to parse versions: %s, Ver: %#v, OVAL: %#v, DefID: %s",
358|				err, req.versionRelease, ovalPack, def.DefinitionID)
359|			return false, false, ovalPack.Version, nil
360|		}
361|		if less {
362|			if req.isSrcPack {
363|				// Unable to judge whether fixed or not-fixed of src package(Ubuntu, Debian)
364|				return true, false, ovalPack.Version, nil
365|			}
366|
367|			// If the version of installed is less than in OVAL
368|			switch family {
369|			case constant.RedHat,
370|				constant.Amazon,
371|				constant.SUSEEnterpriseServer,
372|				constant.Debian,
373|				constant.Ubuntu,
374|				constant.Raspbian,
375|				constant.Oracle:
376|				// Use fixed state in OVAL for these distros.
377|				return true, false, ovalPack.Version, nil
378|			}
379|
380|			// But CentOS can't judge whether fixed or unfixed.
381|			// Because fixed state in RHEL OVAL is different.
382|			// So, it have to be judged version comparison.
383|
384|			// `offline` or `fast` scan mode can't get a updatable version.
385|			// In these mode, the blow field was set empty.
386|			// Vuls can not judge fixed or unfixed.
387|			if req.newVersionRelease == "" {
388|				return true, false, ovalPack.Version, nil
389|			}
390|
391|			// compare version: newVer vs oval
392|			less, err := lessThan(family, req.newVersionRelease, ovalPack)
393|			if err != nil {
394|				logging.Log.Debugf("Failed to parse versions: %s, NewVer: %#v, OVAL: %#v, DefID: %s",
395|					err, req.newVersionRelease, ovalPack, def.DefinitionID)
396|				return false, false, ovalPack.Version, nil
397|			}
398|			return true, less, ovalPack.Version, nil
399|		}
400|	}
401|	return false, false, "", nil
