136|		o.log.Warnf("err: %+v", err)
137|		o.warns = append(o.warns, err)
138|		// Only warning this error
139|	}
140|
141|	packs, err := o.scanInstalledPackages()
142|	if err != nil {
143|		o.log.Errorf("Failed to scan installed packages: %s", err)
144|		return err
145|	}
146|	o.Packages = packs
147|
148|	unsecures, err := o.scanUnsecurePackages()
149|	if err != nil {
150|		o.log.Errorf("Failed to scan vulnerable packages: %s", err)
151|		return err
152|	}
153|	o.VulnInfos = unsecures
154|	return nil
155|}
......
161|func (o *bsd) rebootRequired() (bool, error) {
162|	r := o.exec("freebsd-version -k", noSudo)
163|	if !r.isSuccess() {
164|		return false, xerrors.Errorf("Failed to SSH: %s", r)
165|	}
166|	return o.Kernel.Release != strings.TrimSpace(r.Stdout), nil
167|}
......
169|func (o *bsd) scanInstalledPackages() (models.Packages, error) {
170|	// https://github.com/future-architect/vuls/issues/1042
171|	cmd := util.PrependProxyEnv("pkg info")
172|	r := o.exec(cmd, noSudo)
173|	if !r.isSuccess() {
174|		return nil, xerrors.Errorf("Failed to SSH: %s", r)
175|	}
176|	pkgs := o.parsePkgInfo(r.Stdout)
177|
178|	cmd = util.PrependProxyEnv("pkg version -v")
179|	r = o.exec(cmd, noSudo)
180|	if !r.isSuccess() {
181|		return nil, xerrors.Errorf("Failed to SSH: %s", r)
182|	}
183|	// `pkg-audit` has a new version, overwrite it.
184|	for name, p := range o.parsePkgVersion(r.Stdout) {
185|		pkgs[name] = p
186|	}
187|	return pkgs, nil
188|}
......
190|func (o *bsd) scanUnsecurePackages() (models.VulnInfos, error) {
191|	const vulndbPath = "/tmp/vuln.db"
192|	cmd := "rm -f " + vulndbPath
193|	r := o.exec(cmd, noSudo)
194|	if !r.isSuccess(0) {
195|		return nil, xerrors.Errorf("Failed to SSH: %s", r)
196|	}
197|
198|	cmd = util.PrependProxyEnv("pkg audit -F -r -f " + vulndbPath)
199|	r = o.exec(cmd, noSudo)
200|	if !r.isSuccess(0, 1) {
201|		return nil, xerrors.Errorf("Failed to SSH: %s", r)
202|	}
203|	if r.ExitStatus == 0 {
204|		// no vulnerabilities
205|		return nil, nil
206|	}
207|
208|	packAdtRslt := []pkgAuditResult{}
209|	blocks := o.splitIntoBlocks(r.Stdout)
210|	for _, b := range blocks {
211|		name, cveIDs, vulnID := o.parseBlock(b)
212|		if name == "" || len(cveIDs) == 0 {
213|			continue
214|		}
215|		pack, found := o.Packages[name]
216|		if !found {
217|			return nil, xerrors.Errorf("Vulnerable package: %s is not found", name)
218|		}
219|		packAdtRslt = append(packAdtRslt, pkgAuditResult{
220|			pack: pack,
221|			vulnIDCveIDs: vulnIDCveIDs{
222|				vulnID: vulnID,
223|				cveIDs: cveIDs,
224|			},
225|		})
226|	}
227|
228|	// { CVE ID: []pkgAuditResult }
229|	cveIDAdtMap := make(map[string][]pkgAuditResult)
230|	for _, p := range packAdtRslt {
231|		for _, cid := range p.vulnIDCveIDs.cveIDs {
232|			cveIDAdtMap[cid] = append(cveIDAdtMap[cid], p)
233|		}
234|	}
235|
236|	vinfos := models.VulnInfos{}
237|	for cveID := range cveIDAdtMap {
238|		packs := models.Packages{}
239|		for _, r := range cveIDAdtMap[cveID] {
240|			packs[r.pack.Name] = r.pack
241|		}
242|
243|		disAdvs := []models.DistroAdvisory{}
244|		for _, r := range cveIDAdtMap[cveID] {
245|			disAdvs = append(disAdvs, models.DistroAdvisory{
246|				AdvisoryID: r.vulnIDCveIDs.vulnID,
247|			})
248|		}
249|
250|		affected := models.PackageFixStatuses{}
251|		for name := range packs {
252|			affected = append(affected, models.PackageFixStatus{
253|				Name: name,
254|			})
255|		}
256|		vinfos[cveID] = models.VulnInfo{
257|			CveID:            cveID,
258|			AffectedPackages: affected,
259|			DistroAdvisories: disAdvs,
260|			Confidences:      models.Confidences{models.PkgAuditMatch},
261|		}
262|	}
263|	return vinfos, nil
264|}

