31|// Fire redacts values in an log Entry that match
32|// with keys defined in the RedactionList
33|func (h *Hook) Fire(e *logrus.Entry) error {
34|	if err := h.initRedaction(); err != nil {
35|		return err
36|	}
37|	for _, re := range h.redactionKeys {
38|		// Redact based on key matching in Data fields
39|		for k, v := range e.Data {
40|			if re.MatchString(k) {
41|				e.Data[k] = "[REDACTED]"
42|				continue
43|			}
44|
45|			// Redact based on value matching in Data fields
46|			switch reflect.TypeOf(v).Kind() {
47|			case reflect.String:
48|				e.Data[k] = re.ReplaceAllString(v.(string), "$1[REDACTED]$2")
49|				continue
50|			}
51|		}
52|
53|		// Redact based on text matching in the Message field
54|		e.Message = re.ReplaceAllString(e.Message, "$1[REDACTED]$2")
55|	}
56|
57|	return nil
58|}
