+package cache
+
+import (
+	"context"
+	"testing"
+
+	"github.com/stretchr/testify/assert"
+)
+
+func TestWithDoNotStore(t *testing.T) {
+	ctx := context.Background()
+	ctx = WithDoNotStore(ctx)
+
+	val := ctx.Value(doNotStore)
+	assert.NotNil(t, val)
+	assert.Equal(t, true, val)
