303|// AuditUnaryInterceptor sends audit logs to configured sinks upon successful RPC requests for auditable events.
304|func AuditUnaryInterceptor(logger *zap.Logger) grpc.UnaryServerInterceptor {
305|	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
306|		resp, err := handler(ctx, req)
307|		if err != nil {
308|			return resp, err
309|		}
310|
311|		actor := auth.ActorFromContext(ctx)
312|
313|		var event *audit.Event
314|
315|		defer func() {
316|			if event != nil {
317|				span := trace.SpanFromContext(ctx)
318|				span.AddEvent("event", trace.WithAttributes(event.DecodeToAttributes()...))
319|			}
320|		}()
321|
322|		// Delete request(s) have to be handled separately because they do not
323|		// return the concrete type but rather an *empty.Empty response.
324|		switch r := req.(type) {
325|		case *flipt.DeleteFlagRequest:
326|			event = audit.NewEvent(audit.FlagType, audit.Delete, actor, r)
327|		case *flipt.DeleteVariantRequest:
328|			event = audit.NewEvent(audit.VariantType, audit.Delete, actor, r)
329|		case *flipt.DeleteSegmentRequest:
330|			event = audit.NewEvent(audit.SegmentType, audit.Delete, actor, r)
331|		case *flipt.DeleteDistributionRequest:
332|			event = audit.NewEvent(audit.DistributionType, audit.Delete, actor, r)
333|		case *flipt.DeleteConstraintRequest:
334|			event = audit.NewEvent(audit.ConstraintType, audit.Delete, actor, r)
335|		case *flipt.DeleteNamespaceRequest:
336|			event = audit.NewEvent(audit.NamespaceType, audit.Delete, actor, r)
337|		case *flipt.DeleteRuleRequest:
338|			event = audit.NewEvent(audit.RuleType, audit.Delete, actor, r)
339|		case *flipt.DeleteRolloutRequest:
340|			event = audit.NewEvent(audit.RolloutType, audit.Delete, actor, r)
341|		}
342|
343|		// Short circuiting the middleware here since we have a non-nil event from
344|		// detecting a delete.
345|		if event != nil {
346|			return resp, err
347|		}
348|
349|		action := audit.GRPCMethodToAction(info.FullMethod)
350|
351|		switch r := resp.(type) {
352|		case *flipt.Flag:
353|			if action != "" {
354|				event = audit.NewEvent(audit.FlagType, action, actor, audit.NewFlag(r))
355|			}
356|		case *flipt.Variant:
357|			if action != "" {
358|				event = audit.NewEvent(audit.VariantType, action, actor, audit.NewVariant(r))
359|			}
360|		case *flipt.Segment:
361|			if action != "" {
362|				event = audit.NewEvent(audit.SegmentType, action, actor, audit.NewSegment(r))
363|			}
364|		case *flipt.Distribution:
365|			if action != "" {
366|				event = audit.NewEvent(audit.DistributionType, action, actor, audit.NewDistribution(r))
367|			}
368|		case *flipt.Constraint:
369|			if action != "" {
370|				event = audit.NewEvent(audit.ConstraintType, action, actor, audit.NewConstraint(r))
371|			}
372|		case *flipt.Namespace:
373|			if action != "" {
374|				event = audit.NewEvent(audit.NamespaceType, action, actor, audit.NewNamespace(r))
375|			}
376|		case *flipt.Rollout:
377|			if action != "" {
378|				event = audit.NewEvent(audit.RolloutType, action, actor, audit.NewRollout(r))
379|			}
380|		case *flipt.Rule:
381|			if action != "" {
382|				event = audit.NewEvent(audit.RuleType, action, actor, audit.NewRule(r))
383|			}
384|		case *fauth.CreateTokenResponse:
385|			event = audit.NewEvent(audit.TokenType, audit.Create, actor, r.Authentication.Metadata)
386|		}
387|
388|		return resp, err
389|	}
