553|// syncRotationState compares cluster rotation state with the state of
554|// internal services and performs the rotation if necessary.
555|func (process *TeleportProcess) syncRotationState(conn *Connector) (*rotationStatus, error) {
556|	connectors := process.getConnectors()
557|	ca, err := process.getCertAuthority(conn, services.CertAuthID{
558|		DomainName: conn.ClientIdentity.ClusterName,
559|		Type:       services.HostCA,
560|	}, false)
561|	if err != nil {
562|		return nil, trace.Wrap(err)
563|	}
564|	var status rotationStatus
565|	status.ca = ca
566|	for _, conn := range connectors {
567|		serviceStatus, err := process.syncServiceRotationState(ca, conn)
568|		if err != nil {
569|			return nil, trace.Wrap(err)
570|		}
571|		if serviceStatus.needsReload {
572|			status.needsReload = true
573|		}
574|		if serviceStatus.phaseChanged {
575|			status.phaseChanged = true
576|		}
577|	}
578|	return &status, nil
