334|		case s.eventsC <- event:
335|		case <-s.closeContext.Done():
336|			return
337|		}
338|	}()
339|
340|	for _, m := range s.eventMappings {
341|		if m.matches(event.Name, s.events) {
342|			mappedEvent := Event{Name: m.Out}
343|			s.events[mappedEvent.Name] = mappedEvent
344|			go func(e Event) {
345|				select {
346|				case s.eventsC <- e:
347|				case <-s.closeContext.Done():
348|					return
349|				}
350|			}(mappedEvent)
351|			log.WithFields(logrus.Fields{"in": event.String(), "out": m.String(), trace.Component: teleport.Component(teleport.ComponentProcess, s.id)}).Debugf("Broadcasting mapped event.")
352|		}
353|	}
