775|func (l *AuditLog) unpackFile(fileName string) (readSeekCloser, error) {
776|	basename := filepath.Base(fileName)
777|	unpackedFile := filepath.Join(l.playbackDir, strings.TrimSuffix(basename, filepath.Ext(basename)))
778|
779|	// If client has called GetSessionChunk before session is over
780|	// this could lead to cases when not all data will be returned,
781|	// because unpackFile will be called concurrently with the unfinished write
782|	unpackedInfo, err := os.Stat(unpackedFile)
783|	err = trace.ConvertSystemError(err)
784|	switch {
785|	case err != nil && !trace.IsNotFound(err):
786|		return nil, trace.Wrap(err)
787|	case err == nil:
788|		packedInfo, err := os.Stat(fileName)
789|		if err != nil {
790|			return nil, trace.ConvertSystemError(err)
791|		}
792|		// no new data has been added
793|		if unpackedInfo.ModTime().Unix() >= packedInfo.ModTime().Unix() {
794|			return os.OpenFile(unpackedFile, os.O_RDONLY, 0640)
795|		}
796|	}
797|
798|	start := l.Clock.Now()
799|	dest, err := os.OpenFile(unpackedFile, os.O_CREATE|os.O_RDWR|os.O_TRUNC, 0640)
800|	if err != nil {
801|		return nil, trace.ConvertSystemError(err)
802|	}
803|	source, err := os.OpenFile(fileName, os.O_RDONLY, 0640)
804|	if err != nil {
805|		return nil, trace.ConvertSystemError(err)
806|	}
807|	defer source.Close()
808|	reader, err := gzip.NewReader(source)
809|	if err != nil {
810|		return nil, trace.Wrap(err)
811|	}
812|	defer reader.Close()
813|	if _, err := io.Copy(dest, reader); err != nil {
814|		// Unexpected EOF is returned by gzip reader
815|		// when the file has not been closed yet,
816|		// ignore this error
817|		if err != io.ErrUnexpectedEOF {
818|			dest.Close()
819|			return nil, trace.Wrap(err)
820|		}
821|	}
822|	if _, err := dest.Seek(0, 0); err != nil {
823|		dest.Close()
824|		return nil, trace.Wrap(err)
825|	}
826|	l.Debugf("Uncompressed %v into %v in %v", fileName, unpackedFile, l.Clock.Now().Sub(start))
