311|				continue
312|			}
313|		}
314|
315|		if ovalPack.Arch != "" && req.arch != ovalPack.Arch {
316|			continue
317|		}
318|
319|		// https://github.com/aquasecurity/trivy/pull/745
320|		if strings.Contains(req.versionRelease, ".ksplice1.") != strings.Contains(ovalPack.Version, ".ksplice1.") {
