345|						continue
346|					}
347|				}
348|			}
349|		}
350|
351|		if ovalPack.NotFixedYet {
352|			return true, true, ovalPack.Version, nil
353|		}
354|
355|		// Compare between the installed version vs the version in OVAL
356|		less, err := lessThan(family, req.versionRelease, ovalPack)
357|		if err != nil {
358|			logging.Log.Debugf("Failed to parse versions: %s, Ver: %#v, OVAL: %#v, DefID: %s",
359|				err, req.versionRelease, ovalPack, def.DefinitionID)
360|			return false, false, ovalPack.Version, nil
361|		}
362|		if less {
363|			if req.isSrcPack {
364|				// Unable to judge whether fixed or not-fixed of src package(Ubuntu, Debian)
365|				return true, false, ovalPack.Version, nil
366|			}
367|
368|			// If the version of installed is less than in OVAL
369|			switch family {
370|			case constant.RedHat,
371|				constant.Amazon,
372|				constant.SUSEEnterpriseServer,
373|				constant.Debian,
374|				constant.Ubuntu,
375|				constant.Raspbian,
376|				constant.Oracle:
377|				// Use fixed state in OVAL for these distros.
378|				return true, false, ovalPack.Version, nil
379|			}
380|
381|			// But CentOS/Alma/Rocky can't judge whether fixed or unfixed.
382|			// Because fixed state in RHEL OVAL is different.
383|			// So, it have to be judged version comparison.
384|
385|			// `offline` or `fast` scan mode can't get a updatable version.
386|			// In these mode, the blow field was set empty.
387|			// Vuls can not judge fixed or unfixed.
388|			if req.newVersionRelease == "" {
389|				return true, false, ovalPack.Version, nil
390|			}
391|
392|			// compare version: newVer vs oval
393|			less, err := lessThan(family, req.newVersionRelease, ovalPack)
