395|				logging.Log.Debugf("Failed to parse versions: %s, NewVer: %#v, OVAL: %#v, DefID: %s",
396|					err, req.newVersionRelease, ovalPack, def.DefinitionID)
397|				return false, false, ovalPack.Version, nil
398|			}
399|			return true, less, ovalPack.Version, nil
400|		}
401|	}
