199|func httpGet(url string, req request, resChan chan<- response, errChan chan<- error) {
200|	var body string
201|	var errs []error
202|	var resp *http.Response
203|	count, retryMax := 0, 3
204|	f := func() (err error) {
205|		resp, body, errs = gorequest.New().Timeout(10 * time.Second).Get(url).End()
206|		if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
207|			count++
208|			if count == retryMax {
209|				return nil
210|			}
211|			return xerrors.Errorf("HTTP GET error, url: %s, resp: %v, err: %+v", url, resp, errs)
212|		}
213|		return nil
214|	}
215|	notify := func(err error, t time.Duration) {
216|		logging.Log.Warnf("Failed to HTTP GET. retrying in %s seconds. err: %+v", t, err)
217|	}
218|	err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify)
219|	if err != nil {
220|		errChan <- xerrors.Errorf("HTTP Error %w", err)
221|		return
222|	}
223|	if count == retryMax {
224|		errChan <- xerrors.New("HRetry count exceeded")
225|		return
226|	}
227|
228|	defs := []ovalmodels.Definition{}
229|	if err := json.Unmarshal([]byte(body), &defs); err != nil {
230|		errChan <- xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
231|		return
232|	}
233|	resChan <- response{
234|		request: req,
235|		defs:    defs,
236|	}
